import { Routes, Route } from 'react-router-dom';
import "./App.css";
import "./styles/custom.scss"

import Home from "./pages/Home";
import About from "./pages/About";
import Proyects from "./pages/Proyects";

function App() {
  	return (
		<div className="container-fluid min-vh-100 d-flex justify-content-center align-items-start bg-secondary px-lg-0 pt-5">
			<div className="bg-primary shadow-lg border border-black w-100" style={{ maxWidth: '850px', maxHeight: '90vh', overflowY: 'auto', overflowX: 'hidden'}}>
				<Routes>
					<Route path="/" element={<Home />} />
					<Route path="/about" element={<About />} />
					<Route path="/proyects" element={<Proyects />} />
				</Routes>
			</div>
		</div>
  	);
}

export default App;
